from __future__ import annotations

import csv
import sys
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import Iterable, TextIO


FIELDS = [
    "JobID",
    "User",
    "Partition",
    "State",
    "Submit",
    "Start",
    "End",
    "Elapsed",
    "AllocCPUS",
    "AllocTRES",
    "ExitCode",
]


UNKNOWN_VALUES = {"", "Unknown", "None", "N/A"}


@dataclass(frozen=True)
class JobRecord:
    job_id: str
    user: str
    partition: str
    state: str
    submit: str | None
    start: str | None
    end: str | None
    elapsed_seconds: int
    alloc_cpus: int
    alloc_tres: str
    gpu_count: int
    exit_code: str

    @property
    def cpu_hours(self) -> float:
        return self.elapsed_seconds * self.alloc_cpus / 3600

    @property
    def gpu_hours(self) -> float:
        return self.elapsed_seconds * self.gpu_count / 3600


@dataclass(frozen=True)
class ParseResult:
    records: list[JobRecord]
    total_rows: int
    malformed_rows: int
    skipped_steps: int

    @property
    def malformed_ratio(self) -> float:
        if self.total_rows == 0:
            return 0.0
        return self.malformed_rows / self.total_rows


class RowParseError(ValueError):
    pass


def parse_elapsed(value: str) -> int:
    raw = value.strip()
    if not raw:
        raise RowParseError("missing elapsed value")
    day_part = 0
    time_part = raw
    if "-" in raw:
        days, time_part = raw.split("-", 1)
        if not days.isdigit():
            raise RowParseError(f"invalid elapsed day component: {raw}")
        day_part = int(days)
    pieces = time_part.split(":")
    if len(pieces) != 3 or not all(piece.isdigit() for piece in pieces):
        raise RowParseError(f"invalid elapsed value: {raw}")
    hours, minutes, seconds = (int(piece) for piece in pieces)
    if minutes >= 60 or seconds >= 60:
        raise RowParseError(f"invalid elapsed value: {raw}")
    return day_part * 86400 + hours * 3600 + minutes * 60 + seconds


def parse_alloc_tres(value: str) -> int:
    gpu_count = 0
    for item in value.split(","):
        item = item.strip()
        if not item or "=" not in item:
            continue
        key, raw_value = item.split("=", 1)
        key = key.strip()
        raw_value = raw_value.strip()
        if not key.startswith("gres/gpu"):
            continue
        try:
            gpu_count += int(raw_value)
        except ValueError as exc:
            raise RowParseError(f"invalid GPU count in AllocTRES: {item}") from exc
    return gpu_count


def normalize_timestamp(value: str) -> str | None:
    raw = value.strip()
    if raw in UNKNOWN_VALUES:
        return None
    try:
        datetime.fromisoformat(raw)
    except ValueError as exc:
        raise RowParseError(f"invalid timestamp: {raw}") from exc
    return raw


def parse_since_date(value: str) -> str:
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"invalid ISO date: {value}") from exc
    return parsed.isoformat()


def is_step_job(job_id: str) -> bool:
    return "." in job_id


def parse_row(row: dict[str, str]) -> JobRecord | None:
    missing = [field for field in FIELDS if field not in row]
    if missing:
        raise RowParseError(f"missing fields: {', '.join(missing)}")

    job_id = row["JobID"].strip()
    if not job_id:
        raise RowParseError("missing JobID")
    if is_step_job(job_id):
        return None

    user = row["User"].strip()
    partition = row["Partition"].strip()
    state = row["State"].strip().upper()
    if not user or not partition or not state:
        raise RowParseError("missing user, partition, or state")

    try:
        alloc_cpus = int(row["AllocCPUS"].strip())
    except ValueError as exc:
        raise RowParseError(f"invalid AllocCPUS: {row['AllocCPUS']}") from exc
    if alloc_cpus < 0:
        raise RowParseError(f"invalid AllocCPUS: {alloc_cpus}")

    elapsed_seconds = parse_elapsed(row["Elapsed"])
    gpu_count = parse_alloc_tres(row["AllocTRES"])

    return JobRecord(
        job_id=job_id,
        user=user,
        partition=partition,
        state=state,
        submit=normalize_timestamp(row["Submit"]),
        start=normalize_timestamp(row["Start"]),
        end=normalize_timestamp(row["End"]),
        elapsed_seconds=elapsed_seconds,
        alloc_cpus=alloc_cpus,
        alloc_tres=row["AllocTRES"].strip(),
        gpu_count=gpu_count,
        exit_code=row["ExitCode"].strip() or "Unknown",
    )


def parse_file(path: Path, stderr: TextIO | None = None) -> ParseResult:
    err = stderr or sys.stderr
    records: list[JobRecord] = []
    malformed = 0
    total = 0
    skipped_steps = 0

    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="|")
        if reader.fieldnames != FIELDS:
            found = "|".join(reader.fieldnames or [])
            raise RowParseError(f"invalid header: {found}")
        for line_number, row in enumerate(reader, start=2):
            total += 1
            try:
                record = parse_row(row)
            except RowParseError as exc:
                malformed += 1
                print(f"{path}:{line_number}: skipped malformed row: {exc}", file=err)
                continue
            if record is None:
                skipped_steps += 1
                continue
            records.append(record)

    return ParseResult(records, total, malformed, skipped_steps)


def rows_to_text(rows: Iterable[dict[str, str]]) -> str:
    lines = ["|".join(FIELDS)]
    for row in rows:
        lines.append("|".join(str(row[field]) for field in FIELDS))
    return "\n".join(lines) + "\n"

from __future__ import annotations


def format_duration(seconds: int) -> str:
    days, remainder = divmod(int(seconds), 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, secs = divmod(remainder, 60)
    if days:
        return f"{days}-{hours:02d}:{minutes:02d}:{secs:02d}"
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


def format_hours(value: float | int | None) -> str:
    return f"{float(value or 0):.2f}"


def table(headers: list[str], rows: list[list[object]]) -> str:
    text_rows = [[str(cell) for cell in row] for row in rows]
    widths = [
        max(len(headers[index]), *(len(row[index]) for row in text_rows))
        for index in range(len(headers))
    ]
    lines = [
        "  ".join(header.ljust(widths[index]) for index, header in enumerate(headers)),
        "  ".join("-" * width for width in widths),
    ]
    for row in text_rows:
        lines.append("  ".join(row[index].ljust(widths[index]) for index in range(len(headers))))
    return "\n".join(lines)

